import type { GroupedFinding, Tier } from './types.js'

export const personas = [
  {
    id: 'correctness',
    focus: 'Correctness: boundary conditions, numeric semantics, state ordering, failure paths, API contracts.',
  },
  {
    id: 'security',
    focus: 'Security: injection, authorization and ownership, tenant isolation, secrets, unsafe data flows.',
  },
  {
    id: 'design',
    focus: 'Design: transactionality, error handling, observability, coupling, maintainability with concrete failure impact.',
  },
  {
    id: 'test-integrity',
    focus: 'Test integrity: disabled tests, assertions that cement incorrect behavior, misleading mocks, missing regression coverage.',
  },
] as const

const findingShape = `Each finding must contain title, detail, file, line (integer), line_quote (exact changed code or relevant context), severity (critical|major|minor|nit), and pre_existing (boolean).`

function sharedFinderPrefix(review: string, diff: string, intent?: string): string {
  return `You are a finder in an independent code-review jury. Report only actionable defects supported by this diff; do not speculate about unavailable code. Return no prose outside the structured result.\n${findingShape}\nUse severity nit only for non-blocking style or trivial issues. Mark pre_existing true only when the defect is visible in unchanged/context code rather than introduced by this change. If none, return an empty findings array.\n${review ? `Repository REVIEW.md instructions:\n${review}\n` : ''}${intent ? `The implementation must satisfy the following requirements. Check for omissions and deviations, not only code defects:\n${intent}\n` : ''}Unified diff:\n${diff}`
}

export function finderPrompt(persona: string, focus: string, tier: Tier, review: string, diff: string, intent?: string): string {
  const instruction = tier === 'quick'
    ? 'Use a quick pass. Do not use tools. Inspect implementation and tests, including error semantics, disabled tests, and incorrect assertions. For financial or nullable flows, check rounding consistency and silent fallback to default/full-price behavior. Return at most 8 concrete, high-confidence defects and keep each detail under 400 characters.'
    : 'Use a thorough pass and inspect all relevant changed lines. Do not edit files or run write operations.'
  return `${sharedFinderPrefix(review, diff, intent)}\nFinder persona: ${persona}. ${focus}\n${instruction}`
}

export function voterPrompt(findings: GroupedFinding[], review: string, diff: string, tier: Tier, intent?: string): string {
  const input = findings.map(({ id, title, detail, file, line, line_quote, severity, pre_existing }) => ({
    id, title, detail, file, line, line_quote, severity, pre_existing,
  }))
  const instruction = tier === 'quick' ? 'Do not use tools and keep each reason under 240 characters.' : 'Do not edit files or run write operations.'
  return `You are an independent voter reviewing candidate findings from other agents. Verify every candidate against the supplied diff in one batch. Require a concrete file:line and reproducible reasoning. Return one vote for every input id, with verdict valid, invalid, or uncertain, a concise reason, and evidence {file,line}. Use invalid only when the claim is contradicted or unsupported; use uncertain when the diff cannot establish it. When a proposed authorization fix is inaccurate but the missing authorization/tenant check itself is visible, use uncertain rather than invalid. Do not add findings or return prose outside the structured result.\n${review ? `Repository REVIEW.md instructions:\n${review}\n` : ''}${intent ? `Requirements that must be satisfied when validating intent findings:\n${intent}\n` : ''}Candidates:\n${JSON.stringify(input, null, 2)}\nUnified diff:\n${diff}\n${instruction}`
}

